{"content":"/* styles.css — the frame around the two pictures: night-market colours,
   a readable counter bar, and buttons big enough to hit with a mouse. */

* { box-sizing: border-box; }

body {
  margin: 0;
  background: #171226;
  color: #f2e9d8;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
}

#app { max-width: 1240px; margin: 0 auto; padding: 12px 20px 20px; }

#topbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}

.brand { display: flex; align-items: center; gap: 12px; }
.brand-mark { font-size: 34px; }
h1 { margin: 0; font-size: 28px; letter-spacing: 0.5px; color: #ffd75a; }
.tagline { margin: 2px 0 0; font-size: 13px; color: #c9bfa8; }

.hud { display: flex; gap: 18px; align-items: center; flex-wrap: wrap; }
.hud-item { display: flex; flex-direction: column; gap: 2px; }
.hud-label { font-size: 11px; text-transform: uppercase; letter-spacing: 1px; color: #c9bfa8; }
.hud-item > span:last-child { font-size: 18px; font-weight: 700; }
.timer-item { min-width: 170px; }
.timer-track { width: 170px; height: 8px; background: #33294d; border-radius: 4px; overflow: hidden; }
#timerBar { height: 100%; width: 100%; background: #7fb069; border-radius: 4px; }
#timerBar.low { background: #e2483d; }
#timerBar.mid { background: #e8a13c; }

#counterBar {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 16px;
  margin: 12px 0 10px;
  padding: 10px 16px;
  background: #2a2140;
  border: 2px solid #ffd75a;
  border-radius: 10px;
}
#foundCounter { font-size: 22px; font-weight: 800; color: #ffd75a; white-space: nowrap; }
#levelHint { font-size: 13px; color: #d8cdb4; }

#panels { display: flex; gap: 14px; align-items: flex-start; justify-content: center; }
.panel { margin: 0; }
.panel figcaption { font-size: 14px; font-weight: 700; margin-bottom: 6px; color: #e8dcc0; }
.panel canvas {
  display: block;
  width: 560px;
  height: 420px;
  border: 3px solid #5d4f68;
  border-radius: 8px;
  cursor: crosshair;
  background: #1b2340;
}
.panel canvas:hover { border-color: #ffd75a; }
#versus {
  align-self: center;
  font-size: 22px;
  font-weight: 900;
  color: #ffd75a;
  background: #2a2140;
  border: 2px solid #ffd75a;
  border-radius: 50%;
  width: 52px;
  height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

#controls { display: flex; gap: 10px; align-items: center; margin-top: 14px; flex-wrap: wrap; }
button {
  font-family: inherit;
  font-size: 14px;
  font-weight: 700;
  color: #171226;
  background: #ffd75a;
  border: none;
  border-radius: 8px;
  padding: 10px 14px;
  cursor: pointer;
}
button:hover { background: #ffe08a; }
button:disabled { opacity: 0.45; cursor: default; }
#soundBtn, #restartBtn { background: #8fb8d8; }
#soundBtn:hover, #restartBtn:hover { background: #a8cbe4; }
.level-picker { display: flex; gap: 6px; align-items: center; margin-left: auto; }
.level-picker > span { font-size: 13px; color: #c9bfa8; }
.level-btn { background: #33294d; color: #f2e9d8; font-weight: 600; padding: 8px 10px; }
.level-btn.active { background: #ffd75a; color: #171226; }

#overlay {
  position: fixed;
  inset: 0;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(12, 8, 24, 0.72);
  z-index: 10;
}
#overlay.show { display: flex; }
.overlay-card {
  max-width: 560px;
  margin: 20px;
  padding: 28px 32px;
  background: #241b3a;
  border: 2px solid #ffd75a;
  border-radius: 14px;
  text-align: center;
}
.overlay-card h2 { margin: 0 0 10px; font-size: 26px; color: #ffd75a; }
.overlay-card p { margin: 8px 0; line-height: 1.5; }
#overlayStats { font-size: 18px; font-weight: 700; color: #8fd8a0; }
.overlay-card button { margin-top: 10px; font-size: 16px; padding: 12px 22px; }
.keys { font-size: 12px; color: #c9bfa8; }

footer { margin-top: 14px; text-align: center; font-size: 12px; color: #9a8fa8; }
footer p { margin: 0; }
