{"content":"// shoot.mjs — plays Lantern Lane for real in headless Chromium and takes
// the entry's screenshots from the running game. Run with:
//   node shoot.mjs <game-url> <screenshots-dir>
// It clicks differences with the real mouse, checks the counter, timer,
// hint and keyboard paths, and fails loudly on console errors or any
// request that leaves localhost.

import { chromium } from 'playwright-core';
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';

const [url, outDir] = process.argv.slice(2);
if (!url || !outDir) {
  console.error('usage: node shoot.mjs <game-url> <screenshots-dir>');
  process.exit(2);
}

const CHROME = `${process.env.HOME}/.cache/ms-playwright/chromium-1148/chrome-linux/chrome`;
const failures = [];
const consoleErrors = [];
const outsideRequests = [];

const browser = await chromium.launch({ executablePath: CHROME, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('console', (msg) => {
  if (msg.type() === 'error') consoleErrors.push(msg.text());
});
page.on('pageerror', (err) => consoleErrors.push(String(err)));
page.on('request', (req) => {
  const host = new URL(req.url()).hostname;
  if (host !== '127.0.0.1' && host !== 'localhost') outsideRequests.push(req.url());
});

function check(name, ok, detail = '') {
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail ? ' — ' + detail : ''}`);
  if (!ok) failures.push(name);
}

async function spot() {
  return page.evaluate(() => window.__spot);
}

async function clickDiffOnLeft(diff) {
  const box = await page.locator('#canvasLeft').boundingBox();
  await page.mouse.click(box.x + diff.x, box.y + diff.y);
  await page.waitForTimeout(250);
}

await page.goto(url, { waitUntil: 'load' });
await page.waitForTimeout(600);
let state = await spot();
check('game boots to title screen', state.state === 'title', `state=${state.state}`);

await page.click('#overlayBtn');
await page.waitForTimeout(400);
state = await spot();
check('start button begins level 1', state.state === 'playing' && state.levelIndex === 0, `state=${state.state}`);

// Wrong click first: an empty patch of sky costs 5 seconds.
const timeBefore = (await spot()).timeLeft;
await clickDiffOnLeft({ x: 520, y: 390 });
state = await spot();
check('wrong click costs ~5s, no false find', state.foundCount === 0 && state.timeLeft < timeBefore - 4, `time ${timeBefore.toFixed(1)} -> ${state.timeLeft.toFixed(1)}`);

// Keyboard path: arrows move the crosshair, Space checks (a miss here too).
const timeBeforeKey = (await spot()).timeLeft;
await page.keyboard.press('ArrowRight');
await page.keyboard.press('ArrowRight');
await page.keyboard.press('ArrowDown');
await page.keyboard.press('Space');
await page.waitForTimeout(250);
state = await spot();
check('keyboard crosshair + Space registers a check', state.timeLeft < timeBeforeKey - 4, `time ${timeBeforeKey.toFixed(1)} -> ${state.timeLeft.toFixed(1)}`);

// Find 4 of 7 with the mouse, then take the cover shot.
const level1 = (await spot()).level;
for (const diff of level1.diffs.slice(0, 4)) await clickDiffOnLeft(diff);
state = await spot();
check('4 real clicks found 4 differences', state.foundCount === 4 && state.score === 400, `found=${state.foundCount} score=${state.score}`);
const counter = await page.textContent('#foundCounter');
check('counter reads 4/7 with 3 remain', counter.includes('4 / 7') && counter.includes('3 remain'), counter);
await page.screenshot({ path: join(outDir, '1-cover.jpg'), type: 'jpeg', quality: 82 });

// Two more finds, then a hint: shot 2 shows the hint ring mid-pulse.
for (const diff of level1.diffs.slice(4, 6)) await clickDiffOnLeft(diff);
await page.keyboard.press('h');
await page.waitForTimeout(350);
state = await spot();
check('hint spends one hint and costs points', state.hintsLeft === 2 && state.score === 550, `hints=${state.hintsLeft} score=${state.score}`);
await page.screenshot({ path: join(outDir, '2-hint.jpg'), type: 'jpeg', quality: 82 });

// Last difference -> level-complete overlay over the ringed panels.
await clickDiffOnLeft(level1.diffs[6]);
await page.waitForTimeout(500);
state = await spot();
check('level 1 completes with overlay', state.state === 'levelDone', `state=${state.state}`);
const overlayTitle = await page.textContent('#overlayTitle');
check('overlay celebrates the level', overlayTitle.includes('complete'), overlayTitle);
await page.screenshot({ path: join(outDir, '3-complete.jpg'), type: 'jpeg', quality: 82 });

// Into level 2: find 5 of 10, then take the harbour shot.
await page.click('#overlayBtn');
await page.waitForTimeout(400);
state = await spot();
check('next scene is Harbour Dawn', state.state === 'playing' && state.level.name === 'Harbour Dawn', `level=${state.level.name}`);
const level2 = state.level;
for (const diff of level2.diffs.slice(0, 5)) await clickDiffOnLeft(diff);
state = await spot();
check('5 finds on level 2', state.foundCount === 5, `found=${state.foundCount}`);
await page.screenshot({ path: join(outDir, '4-harbour.jpg'), type: 'jpeg', quality: 82 });

check('no console/page errors', consoleErrors.length === 0, consoleErrors.join(' | '));
check('no requests outside localhost', outsideRequests.length === 0, outsideRequests.join(' | '));

await browser.close();
if (failures.length > 0) {
  console.error(`\n${failures.length} CHECK(S) FAILED`);
  process.exit(1);
}
console.log('\nALL PLAYTEST CHECKS PASSED');
